impl Part {
    fn load(pkg: &PartFs, name: &str) -> Option<Self> {
        let xml = pkg.part_string(name)?;
        let mut dom = Dom::new();
        let doc = dom.parse_xdocument(&xml);
        let root = dom.root(doc)?;
        Some(Self {
            name: name.to_string(),
            dom,
            doc,
            root,
        })

/// Read a part as a UTF-8 string.
pub fn part_string(&self, name: &str) -> Option<String> {
    self.part_bytes(name)
        .map(|b| String::from_utf8_lossy(b).into_owned())
}

pub fn parse_xdocument(dom: &mut Dom, xml: &str) -> NodeId {
    // Strip a leading UTF-8 BOM (U+FEFF): char::is_whitespace() excludes it,
    // so skip_ws() cannot, and an unstripped BOM leaves the document with no root.
    let xml = xml.strip_prefix('\u{feff}').unwrap_or(xml);
    let chars: Vec<char> = xml.chars().collect();
    let mut p = Parser {
        dom,
        c: chars,
        pos: 0,
    };
    p.parse_document()

    if self.cur() == '<' {
        let el = self.parse_element(&mut scope);
        self.dom.add(doc, el);
        continue;
    }
    break;
}
